CREATE TABLE "historico_status_relato" (
                                           "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                           "relato_id" BIGINT NOT NULL,
                                           "status_anterior" varchar(20) NOT NULL,
                                           "status_novo" varchar(20) NOT NULL,
                                           "observacao" text,
                                           "alterado_em" timestamp with time zone NOT NULL,
                                           CONSTRAINT fk_historico_relato
                                               FOREIGN KEY ("relato_id")
                                                   REFERENCES "relatos" ("id")
                                                   ON DELETE CASCADE
);

CREATE INDEX idx_historico_relato_id ON "historico_status_relato" ("relato_id");
